feed:
{{ config.title }}
{%- if term is defined %} - {{ term.name }}
{%- elif section is defined and section.title %} - {{ section.title }}
{%- endif -%}

{%- if config.description %}
{{ config.description }}
{%- endif %}


Zola
{%- set modified_dates = load_data(path="data/last-modified.json", format="json", required=false) %}
{#- The feed changed when its newest entry did, which Zola's last_updated
    does not know: it reads page dates, not the body-edit dates entries use. #}
{%- set_global feed_updated = "" %}
{%- if last_updated is defined %}{% set_global feed_updated = last_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") %}{% endif %}
{%- if modified_dates %}{% for page in pages %}
  {%- set entry_date = modified_dates[page.relative_path] | default(value="") %}
  {%- if entry_date and entry_date > feed_updated %}{% set_global feed_updated = entry_date %}{% endif %}
{%- endfor %}{% endif %}
{% if feed_updated %}{{ feed_updated }}{% endif %}
{{ feed_url | safe }}
{%- for page in pages %}
{%- set_global entry_modified = false %}
{%- if modified_dates and page.relative_path %}
  {%- set_global entry_modified = modified_dates[page.relative_path] | default(value=false) %}
{%- endif %}

    {{ page.title }}
    {%- if page.taxonomies.tags %}
    {%- for tag in page.taxonomies.tags %}

    {%- endfor %}
    {%- endif %}
    {{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
    {% if page.updated %}{{ page.updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% elif entry_modified %}{{ entry_modified }}{% else %}{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% endif %}
    {% for author in page.authors %}


        {{ author }}


    {% else %}


        {%- if config.author -%}
          {{ config.author }}
        {%- else -%}
          Unknown
        {%- endif -%}


    {% endfor %}

    {{ page.permalink | safe }}
    {% if page.description %}
    {{ page.description }}
    {% elif page.summary %}
    {{ page.summary }}
    {% endif %}
    {% if page.content %}
    {{ page.content | escape_xml | safe }}
    {% endif %}

{%- endfor %}
